def minimum_operations(nums):
    # If empty or size 1, no operations needed
    if not nums or len(nums) == 1:
        return 0

    ops = 0
    for i in range(1, len(nums)):
        # Count every change point from previous value
        if nums[i] != nums[i-1]:
            ops += 1
    return ops
